<?php

/* @autogenerated */
declare(strict_types=1);

use PHPUnit\Framework\TestCase;
use Civi\Lughauth\Features\OAuth\User\Application\Usecase\ChangePasswordUsecase;
use Civi\Lughauth\Features\OAuth\User\Application\Usecase\RegisterUserUsecase;
use Civi\Lughauth\Features\OAuth\User\Domain\Gateway\ChangePasswordGateway;
use Civi\Lughauth\Features\OAuth\User\Domain\Gateway\PasswordRecoveryMailGateway;
use Civi\Lughauth\Features\OAuth\User\Domain\Gateway\RegisterUserGateway;
use Civi\Lughauth\Features\OAuth\User\Domain\Gateway\UserRegistrationMailGateway;
use Civi\Lughauth\Features\OAuth\User\Domain\RecoveryNotificationData;
use Civi\Lughauth\Features\OAuth\User\Domain\RegistrationNotificationData;
use Civi\Lughauth\Features\Access\Tenant\Domain\TenantRef;

final class UserUsecasesUnitTest extends TestCase
{
    // --- ChangePasswordUsecase ---

    public function test_change_password_allow_recover_delegates(): void
    {
        $gateway = $this->makeChangePasswordGateway(allowRecover: true);
        $usecase = new ChangePasswordUsecase($gateway, $this->makeRecoveryMailer());
        $this->assertTrue($usecase->allowRecover('tenant'));
    }

    public function test_change_password_request_for_change_does_nothing_when_gateway_returns_null(): void
    {
        $mailSent = false;
        $gateway = $this->makeChangePasswordGateway(requestResult: null);
        $mailer = $this->makeRecoveryMailer(function () use (&$mailSent) { $mailSent = true; });
        $usecase = new ChangePasswordUsecase($gateway, $mailer);

        $usecase->requestForChange('https://auth', 'tenant', 'alice@example.com');

        $this->assertFalse($mailSent);
    }

    public function test_change_password_request_for_change_sends_mail_when_data_returned(): void
    {
        $mailSent = false;
        $data = new RecoveryNotificationData(
            email: 'alice@example.com',
            name: 'Alice',
            tenant: new TenantRef('tenant-uid'),
            recoveryUrl: 'https://auth/recover?token=abc',
            expiresAt: new DateTimeImmutable('+1 hour'),
        );
        $gateway = $this->makeChangePasswordGateway(requestResult: $data);
        $mailer = $this->makeRecoveryMailer(function () use (&$mailSent) { $mailSent = true; });
        $usecase = new ChangePasswordUsecase($gateway, $mailer);

        $usecase->requestForChange('https://auth', 'tenant', 'alice@example.com');

        $this->assertTrue($mailSent);
    }

    public function test_change_password_validate_change_request_delegates(): void
    {
        $gateway = $this->makeChangePasswordGateway(validateResult: 'user-uid-1');
        $usecase = new ChangePasswordUsecase($gateway, $this->makeRecoveryMailer());

        $result = $usecase->validateChangeRequest('tenant', 'code-123', 'newPass123!');
        $this->assertSame('user-uid-1', $result);
    }

    public function test_change_password_force_update_delegates(): void
    {
        $gateway = $this->makeChangePasswordGateway(forceUpdateResult: true);
        $usecase = new ChangePasswordUsecase($gateway, $this->makeRecoveryMailer());

        $this->assertTrue($usecase->forceUpdatePassword('tenant', 'alice', 'old', 'new'));
    }

    // --- RegisterUserUsecase ---

    public function test_register_user_allow_register_delegates(): void
    {
        $gateway = $this->makeRegisterUserGateway(allowRegister: true);
        $usecase = new RegisterUserUsecase($gateway, $this->makeRegistrationMailer());
        $this->assertTrue($usecase->allowRegister('tenant'));
    }

    public function test_register_user_get_register_consent_delegates(): void
    {
        $gateway = $this->makeRegisterUserGateway(registerConsent: 'ToS text here');
        $usecase = new RegisterUserUsecase($gateway, $this->makeRegistrationMailer());
        $this->assertSame('ToS text here', $usecase->getRegisterConsent('tenant'));
    }

    public function test_register_user_request_for_register_does_nothing_when_null(): void
    {
        $mailSent = false;
        $gateway = $this->makeRegisterUserGateway(requestResult: null);
        $mailer = $this->makeRegistrationMailer(function () use (&$mailSent) { $mailSent = true; });
        $usecase = new RegisterUserUsecase($gateway, $mailer);

        $usecase->requestForRegister('https://auth', 'tenant', 'bob@example.com', 'pass');

        $this->assertFalse($mailSent);
    }

    public function test_register_user_request_for_register_sends_mail(): void
    {
        $mailSent = false;
        $data = new RegistrationNotificationData(
            email: 'bob@example.com',
            name: 'Bob',
            tenant: new TenantRef('tenant-uid'),
            activateUrl: 'https://auth/activate?token=xyz',
        );
        $gateway = $this->makeRegisterUserGateway(requestResult: $data);
        $mailer = $this->makeRegistrationMailer(function () use (&$mailSent) { $mailSent = true; });
        $usecase = new RegisterUserUsecase($gateway, $mailer);

        $usecase->requestForRegister('https://auth', 'tenant', 'bob@example.com', 'pass');

        $this->assertTrue($mailSent);
    }

    public function test_register_user_verify_register_delegates(): void
    {
        $gateway = $this->makeRegisterUserGateway(verifyResult: 'user-uid-2');
        $usecase = new RegisterUserUsecase($gateway, $this->makeRegistrationMailer());
        $this->assertSame('user-uid-2', $usecase->verifyRegister('tenant', 'verify-code'));
    }

    // --- helpers ---

    private function makeChangePasswordGateway(
        bool $allowRecover = false,
        ?RecoveryNotificationData $requestResult = null,
        ?string $validateResult = null,
        bool $forceUpdateResult = false,
    ): ChangePasswordGateway {
        return new class($allowRecover, $requestResult, $validateResult, $forceUpdateResult) implements ChangePasswordGateway {
            public function __construct(
                private bool $allowRecover,
                private ?RecoveryNotificationData $requestResult,
                private ?string $validateResult,
                private bool $forceUpdateResult,
            ) {}
            public function requestForChange(string $url, string $tenant, string $username): ?RecoveryNotificationData { return $this->requestResult; }
            public function allowRecover(string $tenant): bool { return $this->allowRecover; }
            public function validateChangeRequest(string $tenant, string $code, string $newPass): ?string { return $this->validateResult; }
            public function forceUpdatePassword(string $tenant, string $username, string $oldPass, string $newPass): bool { return $this->forceUpdateResult; }
        };
    }

    private function makeRecoveryMailer(?callable $onSend = null): PasswordRecoveryMailGateway
    {
        return new class($onSend) implements PasswordRecoveryMailGateway {
            public function __construct(private $onSend) {}
            public function sendPasswordRecovery(string $toEmail, string $userName, \Civi\Lughauth\Features\Access\Tenant\Domain\TenantRef $tenant, string $recoveryUrl, \DateTimeImmutable $expiresAt): void
            {
                if ($this->onSend) { ($this->onSend)(); }
            }
        };
    }

    private function makeRegisterUserGateway(
        bool $allowRegister = false,
        ?string $registerConsent = null,
        ?RegistrationNotificationData $requestResult = null,
        ?string $verifyResult = null,
    ): RegisterUserGateway {
        return new class($allowRegister, $registerConsent, $requestResult, $verifyResult) implements RegisterUserGateway {
            public function __construct(
                private bool $allowRegister,
                private ?string $registerConsent,
                private ?RegistrationNotificationData $requestResult,
                private ?string $verifyResult,
            ) {}
            public function allowRegister(string $tenant): bool { return $this->allowRegister; }
            public function getRegisterConsent(string $tenant): ?string { return $this->registerConsent; }
            public function requestForRegister(string $url, string $tenant, string $email, string $password): ?RegistrationNotificationData { return $this->requestResult; }
            public function verifyRegister(string $tenant, string $code): ?string { return $this->verifyResult; }
        };
    }

    private function makeRegistrationMailer(?callable $onSend = null): UserRegistrationMailGateway
    {
        return new class($onSend) implements UserRegistrationMailGateway {
            public function __construct(private $onSend) {}
            public function sendRegistrationVerification(string $toEmail, string $userName, \Civi\Lughauth\Features\Access\Tenant\Domain\TenantRef $tenant, string $activateUrl): void
            {
                if ($this->onSend) { ($this->onSend)(); }
            }
        };
    }
}
